package com.bank.facilities;

import java.util.logging.*;

public class SqrtDemo {
    private static final Logger log = Logger.getLogger(SqrtDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SqrtService service = new SqrtService();

        log.info("Integer sqrt of 144 (perfect square)");
        log.info("Result -> " + service.integerSqrt(144));

        log.info("Integer sqrt of 200 (not a perfect square)");
        log.info("Result -> " + service.integerSqrt(200));

        log.info("Integer sqrt of 1 and 0 (edge cases)");
        log.info("Result -> sqrt(1)=" + service.integerSqrt(1) + " sqrt(0)=" + service.integerSqrt(0));
    }
}

// ─── Would be in service/SqrtService.java ───
class SqrtService {
    // Largest integer r with r*r <= x. Binary search. O(log x). Long avoids overflow.
    int integerSqrt(int x) {
        if (x < 0) throw new IllegalArgumentException("negative input");
        long low = 0, high = x, answer = 0;
        while (low <= high) {
            long mid = low + (high - low) / 2;  // overflow-safe midpoint
            if (mid * mid <= x) {               // mid is a long -> no overflow
                answer = mid;                   // record valid root, try larger
                low = mid + 1;
            } else {
                high = mid - 1;                 // too big, go smaller
            }
        }
        return (int) answer;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
